refentry.refsect1:
  &reftitle.examples;

   untaint example


<?php
$id = "42";
taint($id);
if (preg_match('/^\d+$/', $id)) {
    // strictly validated as digits: safe to trust
    untaint($id);
}
var_dump(is_tainted($id));
?>


   &example.outputs.similar;


bool(false)

&reftitle.notes;


  Only string values can carry the mark; passing a non-string is a
  no-op.
